alter table public.bookings add column if not exists service_fee_status text not null default 'not_required' check(service_fee_status in ('not_required','pending','paid','refunded'));
alter table public.bookings add column if not exists service_fee_amount numeric(12,2);
alter table public.bookings add column if not exists service_fee_currency text not null default 'BDT';
alter table public.bookings add column if not exists service_fee_paid_at timestamptz;
update public.bookings set service_fee_status='pending' where status in ('Pending','Accepted') and service_fee_status='not_required';
create table if not exists public.platform_payment_methods(id uuid primary key default gen_random_uuid(),method_name text not null,account_label text not null,account_number text not null,instructions text,is_active boolean not null default true,sort_order integer not null default 100,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.platform_payment_methods enable row level security;
drop policy if exists qaaga_payment_methods_read on public.platform_payment_methods;
create policy qaaga_payment_methods_read on public.platform_payment_methods for select to authenticated using(is_active or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_payment_methods_admin_manage on public.platform_payment_methods;
create policy qaaga_payment_methods_admin_manage on public.platform_payment_methods for all to authenticated using((select private.qaaga_is_super_admin())) with check((select private.qaaga_is_super_admin()));
create table if not exists public.service_fee_payment_proofs(id uuid primary key default gen_random_uuid(),ledger_id uuid not null references public.service_fee_ledger(id) on delete restrict,booking_id text not null references public.bookings(id) on delete restrict,customer_id uuid not null references auth.users(id) on delete cascade,customer_email text not null,amount numeric(12,2) not null check(amount>0),currency text not null default 'BDT',payment_method_id uuid not null references public.platform_payment_methods(id) on delete restrict,transaction_reference text not null check(length(trim(transaction_reference)) between 3 and 160),proof_storage_ref text,status text not null default 'pending' check(status in ('pending','verified','rejected')),finance_notes text,reviewed_by text,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_service_fee_proofs_ledger on public.service_fee_payment_proofs(ledger_id,created_at desc);
create index if not exists idx_service_fee_proofs_queue on public.service_fee_payment_proofs(status,created_at desc);
create index if not exists idx_service_fee_proofs_customer on public.service_fee_payment_proofs(customer_id,created_at desc);
alter table public.service_fee_payment_proofs enable row level security;
drop policy if exists qaaga_fee_proofs_read on public.service_fee_payment_proofs;
create policy qaaga_fee_proofs_read on public.service_fee_payment_proofs for select to authenticated using(customer_id=(select auth.uid()) or (select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_fee_proofs_insert on public.service_fee_payment_proofs;
create policy qaaga_fee_proofs_insert on public.service_fee_payment_proofs for insert to authenticated with check(customer_id=(select auth.uid()) and lower(customer_email)=(select private.qaaga_current_email()) and exists(select 1 from public.bookings b where b.id=booking_id and lower(b.customer_email)=(select private.qaaga_current_email()) and b.service_fee_status='pending') and exists(select 1 from public.service_fee_ledger l where l.id=ledger_id and l.booking_id=booking_id and l.status='pending' and l.amount=amount and l.currency=currency) and exists(select 1 from public.platform_payment_methods m where m.id=payment_method_id and m.is_active));
drop policy if exists qaaga_fee_proofs_finance_update on public.service_fee_payment_proofs;
create policy qaaga_fee_proofs_finance_update on public.service_fee_payment_proofs for update to authenticated using((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin())) with check((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()));
create or replace function private.qaaga_on_service_fee_ledger_change() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if tg_op='INSERT' then update public.bookings set service_fee_status='pending',service_fee_amount=new.amount,service_fee_currency=new.currency,updated_at=now() where id=new.booking_id and status in ('Pending','Accepted'); elsif tg_op='UPDATE' and new.status is distinct from old.status then update public.bookings set service_fee_status=case when new.status='paid' then 'paid' when new.status='refunded' then 'refunded' else 'pending' end,service_fee_amount=new.amount,service_fee_currency=new.currency,service_fee_paid_at=case when new.status='paid' then coalesce(new.paid_at,now()) else null end,status=case when new.status='paid' and status='Accepted' then 'Confirmed' else status end,updated_at=now() where id=new.booking_id; end if; return new; end; $$;
revoke all on function private.qaaga_on_service_fee_ledger_change() from public,anon,authenticated;
drop trigger if exists qaaga_on_service_fee_ledger_change on public.service_fee_ledger;
create trigger qaaga_on_service_fee_ledger_change after insert or update of status on public.service_fee_ledger for each row execute function private.qaaga_on_service_fee_ledger_change();
create or replace function private.qaaga_guard_fee_proof_update() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if private.qaaga_is_super_admin() then return new; end if; if not private.qaaga_has_role('finance') then raise exception 'Finance role required.'; end if; if (to_jsonb(new)-array['status','finance_notes','reviewed_by','reviewed_at','updated_at'])<>(to_jsonb(old)-array['status','finance_notes','reviewed_by','reviewed_at','updated_at']) then raise exception 'Finance staff may only update review status and notes.'; end if; if new.status='verified' and old.status<>'pending' then raise exception 'Only pending proofs can be verified.'; end if; return new; end; $$;
revoke all on function private.qaaga_guard_fee_proof_update() from public,anon,authenticated;
drop trigger if exists qaaga_guard_fee_proof_update on public.service_fee_payment_proofs;
create trigger qaaga_guard_fee_proof_update before update on public.service_fee_payment_proofs for each row execute function private.qaaga_guard_fee_proof_update();
create or replace function private.qaaga_on_fee_proof_verified() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if new.status='verified' and old.status='pending' then update public.service_fee_ledger set status='paid',payment_method=(select m.method_name from public.platform_payment_methods m where m.id=new.payment_method_id),external_reference=new.transaction_reference,paid_at=now(),updated_at=now() where id=new.ledger_id and status='pending'; update public.service_fee_payment_proofs set reviewed_at=coalesce(new.reviewed_at,now()) where id=new.id; end if; return new; end; $$;
revoke all on function private.qaaga_on_fee_proof_verified() from public,anon,authenticated;
drop trigger if exists qaaga_on_fee_proof_verified on public.service_fee_payment_proofs;
create trigger qaaga_on_fee_proof_verified after update of status on public.service_fee_payment_proofs for each row execute function private.qaaga_on_fee_proof_verified();
